#include <algorithm>

class Solution {
public:
    int calculateScore(int a, int b) {
        int s1 = __builtin_popcount(a);
        int s2 = __builtin_popcount(b);
        if (s1 >= s2) return s1 * s2;
        return s2 / s1;
    }
};

class Solution {
    public int binaryDigitScore(int[] nums) {
        int score = 0;
        for (int x : nums) score += Integer.bitCount(x);
        return score;
    }
}

var binaryDigitScore = function(nums) {
    let score = 0;
    for (let x of nums) {
        while (x > 0) {
            score += x & 1;
            x >>= 1;
        }
    }
    return score;
};
